'use strict';
const fs=require('fs'),path=require('path'),vm=require('vm'),cp=require('./portable-baseline.cjs');const root=path.resolve(__dirname,'..'),BASELINE='5bb23cb6b1cb4f901af9d07a45a919b4bcd2931f',out=path.resolve(process.env.FOOD_DYNAMIC_OUT_DIR||path.join(__dirname,'food-dynamic-v10'));
let baseline;try{baseline=cp.execFileSync('git',['show',`${BASELINE}:dist/scenes/toaster.js`],{cwd:root,encoding:'utf8',stdio:['ignore','pipe','pipe']});}catch(error){throw new Error(`Cannot read pinned baseline ${BASELINE}. Ensure this commit exists in the local git history. ${error.message}`);}
for(const version of ['before','after']){const dir=path.join(out,version);fs.mkdirSync(dir,{recursive:true});const ctx=vm.createContext({window:{},console,addEventListener(){},Number,Math});vm.runInContext(fs.readFileSync(path.join(root,'dist/core.js'),'utf8'),ctx);vm.runInContext(version==='before'?baseline:fs.readFileSync(path.join(root,'dist/scenes/toaster.js'),'utf8'),ctx);const cfg=ctx.window.SCENES.toaster(),steps=new Set(),ui={animate:f=>steps.add(f),flash(){},invalidate(){}};cfg.state.pal='mint';const tick=d=>{for(const step of [...steps])if(step(d)===false)steps.delete(step)};cfg.acts.load(cfg.state,{},ui);let last=0;const frames=[];for(const k of [.13,.15,.175,.2]){for(let t=last;t<1.15*k-1e-8;t+=.001)tick(Math.min(.001,1.15*k-t));last=1.15*k;for(const yaw of [135,180,225])for(const pitch of [6,35.264,78]){const [W,D,H]=cfg.size;vm.runInContext(`RC=[${W/2},${D/2}];RCZ=${H/2};OX=150;OY=155;INK_K=.5;setCam(${yaw},${pitch});setLight(105);`,ctx);const svg=cfg.scene(cfg.state,vm.runInContext('PALS.mint',ctx));frames.push({k,yaw,pitch,svg});}}
for(const pitch of [6,35.264,78]){const list=frames.filter(f=>f.pitch===pitch);let sheet='<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1540"><rect width="100%" height="100%" fill="#f2efe7"/>';for(const [i,f]of list.entries())sheet+=`<text x="${i%3*360+10}" y="${Math.floor(i/3)*385+18}" font-family="sans-serif" font-size="14">${version} load ${f.k}, yaw ${f.yaw}, pitch ${pitch}</text><svg x="${i%3*360}" y="${Math.floor(i/3)*385+25}" width="360" height="360" viewBox="65 55 180 180">${f.svg}</svg>`;sheet+='</svg>';const name=path.join(dir,`toaster-crossing-pitch${pitch}`);fs.writeFileSync(name+'.svg',sheet);cp.execFileSync('inkscape',[name+'.svg',`--export-filename=${name}.png`],{stdio:'pipe'});}}
console.log('Rendered actual-action lid crossing at .13, .15, .175, .2 in rear three views at low, standard, high pitch, before and after.');
